suppressPackageStartupMessages(library(limma))
O<-'/mnt/BioDisk/wangmingyuan/GI_preanalysis_20260923/CRC_routes_v1/deep_v2';R<-file.path(O,'results/bulk_validation');dir.create(R,recursive=TRUE,showWarnings=FALSE)
x<-read.delim(gzfile(file.path(O,'raw/bulk_FPKM.tsv.gz')),row.names=1,check.names=FALSE);m<-read.delim(file.path(O,'metadata/bulk_design.tsv'),check.names=FALSE);m<-m[m$site%in%c('PT','LM'),];m$patient<-factor(m$patient);m$site<-factor(m$site,levels=c('PT','LM'));x<-as.matrix(x[,m$sample]);stopifnot(ncol(x)==36,length(unique(m$patient))==18);keep<-rowSums(x>=1)>=6;E<-log2(x[keep,,drop=FALSE]+1);allE<-log2(x+1)
sets<-list(hepatic=c('ALB','FGA','FGB','FGG','APOA1','APOA2','TTR','HP','AGT','GC','CRP'),stromal=c('COL1A1','COL1A2','DCN','LUM'),epithelial=c('EPCAM','KRT8','KRT18','KRT19'))
cov<-data.frame();for(n in names(sets)){hit<-intersect(sets[[n]],rownames(allE));stopifnot(length(hit)>=.8*length(sets[[n]]));m[[n]]<-colMeans(allE[hit,,drop=FALSE]);cov<-rbind(cov,data.frame(proxy=n,measured=paste(hit,collapse=';'),missing=paste(setdiff(sets[[n]],hit),collapse=';')))}
write.table(cov,file.path(R,'proxy_coverage.tsv'),sep='\t',quote=FALSE,row.names=FALSE);write.table(m,file.path(R,'sample_values.tsv'),sep='\t',quote=FALSE,row.names=FALSE)
map<-read.delim(file.path(O,'metadata/candidate_symbol_map.tsv'),check.names=FALSE);stopifnot(nrow(map)==126);forms<-list(main=~patient+site,hepatic=~patient+hepatic+site,composition=~patient+stromal+epithelial+site,combined=~patient+hepatic+stromal+epithelial+site);out<-list();diag<-data.frame()
writeLines(c('FPKM data: log2(FPKM+1), paired limma-trend. No voom/count-based model.','Filter FPKM>=1 in at least6 of36 PT/LM samples, before candidate outcomes.','Four models: paired main; hepatic proxy; stromal+epithelial; combined. Genomewide BH per model; separately fixed126 candidate family per model, absent/unfiltered kept as1 in multiplicity.','CRC validation: patient-level colon/rectum not established by GEO; no pooling with discovery cells.'),file.path(R,'MODEL_PLAN.txt'))
for(k in names(forms)){
 d<-model.matrix(forms[[k]],m);stopifnot(qr(d)$rank==ncol(d));fit<-eBayes(lmFit(E,d),trend=TRUE);t<-topTable(fit,coef='siteLM',number=Inf,sort.by='none',confint=TRUE);t$gene<-rownames(t);write.table(t,gzfile(file.path(R,paste0(k,'_all_genes.tsv.gz'))),sep='\t',quote=FALSE,row.names=FALSE);z<-merge(map,t,by.x='bulk_gene',by.y='gene',all.x=TRUE,sort=FALSE);stopifnot(nrow(z)==126);p<-z$P.Value;p[is.na(p)]<-1;z$FDR_fixed126<-p.adjust(p,'BH');z$FDR_fixed126[is.na(z$P.Value)]<-NA;z$model<-k;out[[k]]<-z;diag<-rbind(diag,data.frame(model=k,genes=nrow(E),n_samples=nrow(d),rank=qr(d)$rank,residual_df=nrow(d)-qr(d)$rank,condition_number=kappa(d)))
}
z<-do.call(rbind,out);write.table(z,file.path(R,'candidate_validation_all_models.tsv'),sep='\t',quote=FALSE,row.names=FALSE);write.table(diag,file.path(R,'model_diagnostics.tsv'),sep='\t',quote=FALSE,row.names=FALSE)
pts<-levels(m$patient);delta<-sapply(pts,function(p){allE[,m$patient==p&m$site=='LM']-allE[,m$patient==p&m$site=='PT']});colnames(delta)<-pts;write.table(data.frame(gene=rownames(delta),delta),gzfile(file.path(R,'all_gene_paired_differences.tsv.gz')),sep='\t',quote=FALSE,row.names=FALSE);ds<-data.frame(gene=rownames(delta),positive=rowSums(delta>0),negative=rowSums(delta<0),median_delta=apply(delta,1,median));write.table(ds,file.path(R,'pair_concordance.tsv'),sep='\t',quote=FALSE,row.names=FALSE);write.table(data.frame(gene=rownames(E),E),gzfile(file.path(R,'log2FPKM_filtered.tsv.gz')),sep='\t',quote=FALSE,row.names=FALSE)
writeLines(paste('exit_code=0; pairs=18; tested_genes=',nrow(E),'; frozen_family=126; models=4',sep=''),file.path(R,'COMPLETE.txt'));print(diag);print(as.data.frame(z[z$model=='main'&!is.na(z$FDR_fixed126)&z$FDR_fixed126<.05,c('candidate','logFC','P.Value','adj.P.Val','FDR_fixed126')]))
